from pathlib import Path
import os,subprocess,json
src=Path('/root/iptvpn_bot')
base=Path('/srv/projects')
dst=base/'iptvpn-bot'
def call(args,sec=12):
 return subprocess.run(args,capture_output=True,text=True,timeout=sec)
def active(name):
 return call(['systemctl','is-active',name+'.service'],8).stdout.strip()
def pm_status():
 proc=call(['pm2','jlist'],18)
 if proc.returncode:raise RuntimeError('PM2 unavailable')
 result={}
 for a in json.loads(proc.stdout):
  if a.get('name') in ('iptvpn_bot','telegram-robot-leads'):
   env=a.get('pm2_env') or {}
   result[a.get('name')]={'status':env.get('status'),'pid':a.get('pid'),'cwd':env.get('pm_cwd')}
 return result
protect=['pink-iptv-backend','pink-vpn','fadego-staging','lowcost-europa','pm2-root','nginx','postgresql@16-main','ssh']
services={x:active(x) for x in protect}
if any(v!='active' for v in services.values()):raise RuntimeError('Protected service inactive pre-move')
bots_before=pm_status()
if any(bots_before.get(x,{}).get('status')!='online' for x in ('iptvpn_bot','telegram-robot-leads')):raise RuntimeError('Bot preflight failed')
if not src.is_dir() or src.is_symlink() or src.stat().st_uid!=0 or dst.exists() or dst.is_symlink():
 raise RuntimeError('Unexpected old/new installation paths')
if base.exists() or base.is_symlink():raise RuntimeError('Canonical parent already exists; inspect first')
if src.stat().st_dev!=Path('/srv').stat().st_dev:raise RuntimeError('Not an atomic filesystem move')
origin=call(['git','-C',str(src),'remote','get-url','origin'],12)
if origin.returncode or 'martaxi-boss/iptvpn-bot' not in origin.stdout:raise RuntimeError('Git remote does not match project')
old_status=call(['git','-C',str(src),'status','--porcelain','--untracked-files=no'],12)
if old_status.returncode:raise RuntimeError('Git status failed')
dsize=call(['du','-x','-s','-B1',str(src)],35)
if dsize.returncode:raise RuntimeError('Directory size preflight failed')
size=int(dsize.stdout.split()[0])
inode=src.stat().st_ino
if not (src/'start.sh').is_file() or not (src/'.venv/bin/python3').exists():raise RuntimeError('Entrypoint or venv missing')
print('OLD_REAL_ROOT='+str(src))
print('CANONICAL_ROOT='+str(dst))
print('BYTES_TO_MOVE='+str(size))
base.mkdir(mode=0o755)
moved=False
try:
 src.rename(dst)
 moved=True
 src.symlink_to(dst,target_is_directory=True)
 if not src.is_symlink() or src.resolve()!=dst or not dst.is_dir() or dst.stat().st_ino!=inode:raise RuntimeError('Canonical path verification failed')
 if not (dst/'start.sh').is_file():raise RuntimeError('Start script missing')
 if call(['/bin/bash','-n',str(dst/'start.sh')],9).returncode:raise RuntimeError('Start script syntax invalid')
 v=call([str(dst/'.venv/bin/python3'),'-c','import sys,telethon; assert sys.version_info.major==3'],14)
 if v.returncode:raise RuntimeError('Python venv import test failed')
 after=call(['git','-C',str(dst),'status','--porcelain','--untracked-files=no'],12)
 if after.returncode or after.stdout!=old_status.stdout:raise RuntimeError('Git tracked state changed')
 d2=call(['du','-x','-s','-B1',str(dst)],35)
 if d2.returncode or int(d2.stdout.split()[0])!=size:raise RuntimeError('Project content size changed')
 for name,old in services.items():
  if active(name)!=old:raise RuntimeError('Protected systemd service changed: '+name)
 bots_after=pm_status()
 for name in ('iptvpn_bot','telegram-robot-leads'):
  old=bots_before[name];new=bots_after.get(name,{})
  if new.get('status')!='online' or new.get('pid')!=old.get('pid'):
   raise RuntimeError('Bot process state changed: '+name)
except Exception:
 if src.is_symlink() and src.resolve()==dst:src.unlink()
 if moved and dst.exists() and not src.exists():dst.rename(src)
 if base.exists() and not list(base.iterdir()):base.rmdir()
 print('PATH_MIGRATION_ROLLBACK=APPLIED')
 raise
print('CANONICAL_PROJECT_PRESENT='+str(dst.is_dir()))
print('OLD_PATH_COMPAT_LINK='+str(src)+' -> '+str(src.resolve()))
print('OLD_DIRECTORY_NO_LONGER_PHYSICAL='+str(src.is_symlink()))
print('DIRECTORY_SIZE_VERIFIED='+str(size))
print('PYTHON_VENV_IMPORT=PASS')
print('SCRIPT_SYNTAX=PASS')
print('GIT_TRACKED_STATUS_UNCHANGED=YES')
for name in ('iptvpn_bot','telegram-robot-leads'):
 print('BOT|'+name+'|online|PID='+str(bots_after[name]['pid']))
print('SYSTEMD_SERVICES=UNCHANGED')
print('SPACE_FREED_BYTES=0')
print('IPTVPN_CANONICAL_PHYSICAL_RELOCATION=PASS')
